-- ============ Part 2: rules, security, data merge (hand-written) ============

ALTER TABLE organizations
  ADD CONSTRAINT organizations_timesheet_period_check CHECK (timesheet_period IN ('WEEKLY', 'BIWEEKLY', 'MONTHLY')),
  ADD CONSTRAINT organizations_timesheet_period_anchor_check CHECK (EXTRACT(ISODOW FROM timesheet_period_anchor) = 1),
  ADD CONSTRAINT organizations_manual_time_limit_check CHECK (manual_time_limit_minutes BETWEEN 0 AND 480),
  ADD CONSTRAINT organizations_timesheet_variance_check CHECK (timesheet_variance_pct BETWEEN 5 AND 50),
  ADD CONSTRAINT organizations_timesheet_due_days_check CHECK (timesheet_submit_due_days BETWEEN 0 AND 14);

ALTER TABLE project_members
  ADD CONSTRAINT project_members_rate_override_check CHECK (rate_override IS NULL OR rate_override >= 0);

ALTER TABLE subcontractor_profiles
  ADD CONSTRAINT subcontractor_profiles_rate_type_check CHECK (rate_type IN ('HOURLY', 'DAILY', 'FIXED')),
  ADD CONSTRAINT subcontractor_profiles_rate_check CHECK (rate >= 0),
  ADD CONSTRAINT subcontractor_profiles_currency_check CHECK (currency ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT subcontractor_profiles_multiplier_check CHECK (overtime_multiplier >= 1 AND overtime_multiplier < 10),
  ADD CONSTRAINT subcontractor_profiles_cap_check CHECK (weekly_hours_cap IS NULL OR (weekly_hours_cap > 0 AND weekly_hours_cap <= 168));

ALTER TABLE timesheets
  ADD CONSTRAINT timesheets_status_check CHECK (status IN ('DRAFT', 'SUBMITTED', 'APPROVED', 'REJECTED', 'LOCKED', 'PAID')),
  ADD CONSTRAINT timesheets_period_check CHECK (period_end >= period_start AND period_end - period_start <= 31),
  ADD CONSTRAINT timesheets_minutes_check CHECK (attendance_minutes >= 0 AND logged_minutes >= 0 AND billable_minutes >= 0 AND flagged_days >= 0),
  ADD CONSTRAINT timesheets_amount_check CHECK (amount IS NULL OR amount >= 0),
  ADD CONSTRAINT timesheets_currency_check CHECK (currency IS NULL OR currency ~ '^[A-Z]{3}$');

ALTER TABLE timesheet_days
  ADD CONSTRAINT timesheet_days_minutes_check CHECK (attendance_minutes >= 0 AND logged_minutes >= 0 AND manual_minutes >= 0);

ALTER TABLE time_entries
  ADD CONSTRAINT time_entries_source_check CHECK (source IN ('TIMER', 'MANUAL', 'AUTO_FROM_ATTENDANCE')),
  ADD CONSTRAINT time_entries_minutes_check CHECK (minutes BETWEEN 0 AND 1440),
  ADD CONSTRAINT time_entries_manual_reason_check CHECK (source <> 'MANUAL' OR length(btrim(coalesce(manual_reason, ''))) >= 3),
  ADD CONSTRAINT time_entries_range_check CHECK (ended_at IS NULL OR started_at IS NULL OR ended_at >= started_at),
  ADD CONSTRAINT time_entries_running_check CHECK (ended_at IS NOT NULL OR (source = 'TIMER' AND started_at IS NOT NULL));

ALTER TABLE timesheet_approvals
  ADD CONSTRAINT timesheet_approvals_action_check CHECK (action IN ('SUBMIT', 'APPROVE', 'REJECT', 'REOPEN'));

-- FR-TS-003: one running timer per user, enforced by the database.
CREATE UNIQUE INDEX time_entries_one_running_timer ON time_entries (org_id, user_id) WHERE ended_at IS NULL;

-- FR-TS-006: entries of a submitted or approved timesheet are locked, whatever the caller.
-- Cascading deletes (an organisation or user being removed) are not blocked.
CREATE FUNCTION fn_time_entries_lock_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  st TEXT;
BEGIN
  IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 THEN
    RETURN OLD;
  END IF;
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    SELECT status INTO st FROM timesheets WHERE id = OLD.timesheet_id;
    IF st IS NOT NULL AND st NOT IN ('DRAFT', 'REJECTED') THEN
      RAISE EXCEPTION 'timesheet is %, its time entries are locked', st USING ERRCODE = 'P0001', HINT = 'TIMESHEET_LOCKED';
    END IF;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    SELECT status INTO st FROM timesheets WHERE id = NEW.timesheet_id;
    IF st IS NOT NULL AND st NOT IN ('DRAFT', 'REJECTED') THEN
      RAISE EXCEPTION 'timesheet is %, its time entries are locked', st USING ERRCODE = 'P0001', HINT = 'TIMESHEET_LOCKED';
    END IF;
    RETURN NEW;
  END IF;
  RETURN OLD;
END
$$;

CREATE TRIGGER time_entries_lock_guard
  BEFORE INSERT OR UPDATE OR DELETE ON time_entries
  FOR EACH ROW EXECUTE FUNCTION fn_time_entries_lock_guard();

-- ---- Row-Level Security

DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['subcontractor_profiles', 'timesheets', 'timesheet_days', 'time_entries', 'timesheet_approvals'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR ALL
         USING (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)
         WITH CHECK (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)',
      t || '_org_policy', t);
  END LOOP;
END
$$;

GRANT SELECT, INSERT, UPDATE ON subcontractor_profiles, timesheets, timesheet_days TO hrvo_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON time_entries TO hrvo_app;
GRANT SELECT, INSERT ON timesheet_approvals TO hrvo_app;
REVOKE DELETE, TRUNCATE ON subcontractor_profiles, timesheets, timesheet_days FROM hrvo_app;
REVOKE UPDATE, DELETE, TRUNCATE ON timesheet_approvals FROM hrvo_app;
REVOKE TRUNCATE ON time_entries FROM hrvo_app;
-- The legacy table is closed to the application; only the migration owner can read it.
REVOKE ALL ON draft_timesheets_legacy FROM hrvo_app;

-- Scheduled jobs also need the timesheet settings (still ids and settings only).
DROP FUNCTION fn_list_orgs_for_jobs();
CREATE FUNCTION fn_list_orgs_for_jobs()
RETURNS TABLE (id UUID, timezone VARCHAR, task_acceptance_escalation_hours INT, timesheet_submit_due_days INT)
SECURITY DEFINER
SET search_path = public
LANGUAGE sql STABLE AS $$
  SELECT o.id, o.timezone, o.task_acceptance_escalation_hours, o.timesheet_submit_due_days FROM organizations o ORDER BY o.id;
$$;
REVOKE ALL ON FUNCTION fn_list_orgs_for_jobs() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_list_orgs_for_jobs() TO hrvo_app;

-- ---- Data merge: every draft_timesheets row becomes a timesheet_days row inside the weekly
-- timesheet (the default period) of its date. Fails loudly instead of skipping rows that RLS
-- would hide from a non-superuser migration role.
SET row_security = off;

INSERT INTO timesheets (org_id, user_id, period_start, period_end)
SELECT DISTINCT d.org_id, d.user_id,
       date_trunc('week', d.work_date::date)::date,
       date_trunc('week', d.work_date::date)::date + 6
FROM draft_timesheets_legacy d
ON CONFLICT (org_id, user_id, period_start) DO NOTHING;

INSERT INTO timesheet_days (org_id, user_id, work_date, timesheet_id, attendance_minutes, logged_minutes, variance_minutes, updated_at)
SELECT d.org_id, d.user_id, d.work_date::date, t.id,
       GREATEST(d.attendance_minutes, 0), GREATEST(d.logged_minutes, 0), d.logged_minutes - d.attendance_minutes, d.updated_at
FROM draft_timesheets_legacy d
JOIN timesheets t ON t.org_id = d.org_id AND t.user_id = d.user_id
 AND t.period_start = date_trunc('week', d.work_date::date)::date
ON CONFLICT (org_id, user_id, work_date) DO NOTHING;

UPDATE timesheets t SET
  attendance_minutes = s.att, logged_minutes = s.logged, variance_minutes = s.logged - s.att
FROM (
  SELECT timesheet_id, SUM(attendance_minutes)::int AS att, SUM(logged_minutes)::int AS logged
  FROM timesheet_days GROUP BY timesheet_id
) s
WHERE s.timesheet_id = t.id;

DO $$
DECLARE
  legacy BIGINT;
  merged BIGINT;
BEGIN
  SELECT count(*) INTO legacy FROM draft_timesheets_legacy;
  SELECT count(*) INTO merged FROM draft_timesheets_legacy d
    JOIN timesheet_days td ON td.org_id = d.org_id AND td.user_id = d.user_id AND td.work_date = d.work_date::date;
  IF legacy <> merged THEN
    RAISE EXCEPTION 'draft_timesheets merge incomplete: % legacy rows, % merged', legacy, merged;
  END IF;
END
$$;

RESET row_security;
